 z=E[["pair_max_fractional_difference","delta_q_mmol_g"]].copy();z["bin"]=pd.qcut(z.pair_max_fractional_difference,10,duplicates="drop");g=z.groupby("bin",observed=True).agg(x=("pair_max_fractional_difference","median"),y=("delta_q_mmol_g","median"),q25=("delta_q_mmol_g",lambda a:a.quantile(.25)),q75=("delta_q_mmol_g",lambda a:a.quantile(.75))).reset_index(drop=True);x=100*g.x.to_numpy();ax.fill_between(x,g.q25,g.q75,color=PALETTE["sky"],alpha=.23,lw=0);ax.plot(x,g.y,marker="o",ms=4,lw=1.3,color=PALETTE["blue"]);ax.axhline(0,color=PALETTE["ink"],lw=.8);ax.set(xlabel="Maximum frozen pair difference (%)",ylabel=r"Median $\Delta q$ (mmol g$^{-1}$)",xlim=(0,None));clean_axis(ax);panel_label(ax,"D")
