 ap=argparse.ArgumentParser();ap.add_argument("--project-root",type=Path,required=True);ap.add_argument("--output-dir",type=Path,required=True);a=ap.parse_args();out=a.output_dir.resolve();out.mkdir(parents=True,exist_ok=True);apply_style();(E,S,T,D),src=load(a.project_root.resolve());fig=plt.figure(figsize=(7.15,5.4));gs=fig.add_gridspec(2,2,left=.09,right=.98,bottom=.10,top=.965,wspace=.46,hspace=.48,width_ratios=[1,1]);A=fig.add_subplot(gs[0,0]);B=fig.add_subplot(gs[0,1]);C=fig.add_subplot(gs[1,0]);Dax=fig.add_subplot(gs[1,1]);aplot(A,E,S);bplot(B,T,S);cplot(C,D);dplot(Dax,E);outs=export_figure(fig,out/"Figure_2_concept");plt.close(fig);save_manifest(out/"Figure_2_concept_manifest.json",script=Path(__file__).name,sources=src,outputs=outs,plotting_only_aggregation=["Panel D descriptive geometry-contrast deciles"],notes={"panel_migration":"Bootstrap histogram and topology-response audit are omitted from the concept main figure; retain in SI/archive."})
